<math dir="rtl" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mi mathvariant="normal">ت</mi><mo>=</mo><mn dir="ltr">٨</mn><mo>+</mo><mn dir="ltr">١</mn><mo>−</mo><mo stretchy="false">[</mo><msup><mi mathvariant="normal">س</mi><mn dir="ltr">٣</mn></msup><msubsup><mo stretchy="false">]</mo><mn dir="ltr">١</mn><mn dir="ltr">٤</mn></msubsup><mo>=</mo><mn dir="ltr">٩</mn><mo>−</mo><mo stretchy="false">(</mo><mn dir="ltr">٦٤</mn><mo>−</mo><mn dir="ltr">١</mn><mo stretchy="false">)</mo><mo>=</mo><mo>−</mo><mn dir="ltr">٥٤</mn></mrow></math>
