<math dir="rtl" xmlns="http://www.w3.org/1998/Math/MathML" display="block"><mrow><mn dir="ltr">٢</mn><mi mathvariant="normal">ب</mi><mo>=</mo><mo>−</mo><mn dir="ltr">٢</mn><mo>−</mo><mfrac><mn dir="ltr">٦</mn><mn dir="ltr">٥</mn></mfrac><mo>=</mo><mo>−</mo><mfrac><mn dir="ltr">١٦</mn><mn dir="ltr">٥</mn></mfrac></mrow></math>
